/* 日付で13年を引く（きょう／誕生日 共通） */
function drawDay(m,d,out,headText,noteExact,noteNear){
 var k=('0'+m).slice(-2)+('0'+d).slice(-2);
 var cnt=DAYCNT[k]||'00000000000000';
 var cells='';
 for(var i=0;i<14;i++){
  var y=2011+i;
  if(y===2011&&m<7)continue;
  if(y===2024&&m>1)continue;
  var c=+cnt.charAt(i);
  cells+='<div class="tdc'+(c?' on':'')+'"><b>'+y+'</b><span>'+(c?c+'件':'—')+'</span></div>';
 }
 var exact=RP.filter(function(q){return q[1]===m&&q[2]===d;});
 var pick=null,note='';
 if(exact.length){
  pick=exact[Math.floor(Math.random()*exact.length)];
  note=noteExact;
 }else{
  var best=null,bd=1e9;
  RP.forEach(function(q){
   var A=new Date(2001,m-1,d),B=new Date(2001,q[1]-1,q[2]);
   var diff=Math.abs(A-B)/86400000; diff=Math.min(diff,365-diff);
   if(diff<bd){bd=diff;best=q;}
  });
  pick=best;
  if(pick)note=noteNear.replace('{M}',pick[1]).replace('{D}',pick[2]);
 }
 out.innerHTML='<p class="tdhead"></p><div class="tdstrip">'+cells+'</div>'+
  '<p class="tdfoot">数えているのは1,992件ぜんぶです。</p>';
 out.querySelector('.tdhead').textContent=headText;
 if(pick){
  var c2=document.createElement('div');c2.className='fbc';
  c2.innerHTML='<div class="fbh"><img class="fbav" src="'+AV+'" alt=""><span class="fbwho"><b>ヤスムラ ミチヨシ</b><time>'+pick[0]+'年'+pick[1]+'月'+pick[2]+'日</time></span><span class="fborg">その日の記録</span></div><p class="tdnote"></p><p class="fbt"></p>';
  c2.querySelector('.tdnote').textContent=note;
  c2.querySelector('.fbt').textContent=pick[3];
  out.appendChild(c2);
 }
 out.hidden=false;
 out.classList.remove('pop');void out.offsetWidth;out.classList.add('pop');
 out.scrollIntoView({behavior:'smooth',block:'center'});
}
