/* KVタイトルの文字ポップ */
try{
 var kvh=document.querySelector('.kv h1');
 if(kvh && !matchMedia('(prefers-reduced-motion: reduce)').matches){
  var di=0;
  kvh.innerHTML=kvh.innerHTML.split(/(<br\s*\/?>)/i).map(function(part){
   if(/^<br/i.test(part))return part;
   var chars=[];
   for(var i=0;i<part.length;i++){
    var c=part.charAt(i);
    if('。、！？」'.indexOf(c)>=0&&chars.length){chars[chars.length-1]+=c;}
    else{chars.push(c);}
   }
   return chars.map(function(c){return '<span class="ch" style="--d:'+(di++)+'">'+c+'</span>';}).join('');
  }).join('');
 }
}catch(e){}
/* statsの数字カウントアップ */
try{
 if(window.IntersectionObserver && !matchMedia('(prefers-reduced-motion: reduce)').matches){
  var cio=new IntersectionObserver(function(es){es.forEach(function(en){
   if(!en.isIntersecting)return;
   var el=en.target;cio.unobserve(el);
   var txt=el.textContent,num=parseInt(txt.replace(/,/g,''),10);
   if(!num||num<10)return;
   var t0=performance.now(),D=950;
   requestAnimationFrame(function tick(t){
    var pr=Math.min((t-t0)/D,1);pr=1-Math.pow(1-pr,3);
    el.textContent=Math.round(num*pr).toLocaleString();
    if(pr<1)requestAnimationFrame(tick);else el.textContent=txt;
   });
  });},{threshold:.6});
  document.querySelectorAll('.card .v').forEach(function(v){cio.observe(v)});
 }
}catch(e){}

/* その頃の一枚: 章に入るとランダムに1枚ポップ */
try{
 if(window.IntersectionObserver){
  var peekShown={}, peekEl=null, peekTimer=null;
  function killPeek(){
   if(peekEl){var e=peekEl;peekEl=null;e.classList.add('out');setTimeout(function(){e.remove();},450);}
   if(peekTimer){clearTimeout(peekTimer);peekTimer=null;}
  }
  function showPeek(sec){
   var imgs=sec.querySelectorAll('.wallgrid img');
   if(!imgs.length)return;
   killPeek();
   var src=imgs[Math.floor(Math.random()*imgs.length)].src;
   var d=document.createElement('div');d.className='peek';
   d.innerHTML='<img alt=""><span class="pk-l">この章の記録から、1枚</span><button class="pk-x" aria-label="閉じる">×</button>';
   d.querySelector('img').src=src;
   d.querySelector('img').addEventListener('click',function(){
    var lb=document.getElementById('lb');
    if(lb){lb.querySelector('img').src=src;lb.querySelector('figcaption').textContent='';lb.showModal();}
   });
   d.querySelector('.pk-x').addEventListener('click',function(ev){ev.stopPropagation();killPeek();});
   document.body.appendChild(d);
   peekEl=d;
   peekTimer=setTimeout(killPeek, 8000);
  }
  var pio=new IntersectionObserver(function(es){es.forEach(function(e){
   if(!e.isIntersecting)return;
   var sec=e.target, name=sec.getAttribute('data-chname')||'';
   if(peekShown[name])return;
   peekShown[name]=1;
   setTimeout(function(){showPeek(sec);},1900);
  });},{rootMargin:'-35% 0px -35% 0px'});
  document.querySelectorAll('section[data-chname]').forEach(function(sec){
   if(sec.querySelector('.wallgrid'))pio.observe(sec);
  });
 }
}catch(e){}

