/* ===== 顔ウォール =====
   13年分の写真から集めた顔を並べ、クリックするとその人の写真が出る。
   顔の照合はしない（アーカイブの顔は中央値66pxで、照合すると他人が出るため）。
   クリックした顔と写真の対応は確定情報なので、外れることがない。 */
(function(){
 try{
  var wrap=document.getElementById('facewrap');
  var grid=document.getElementById('wallgridf');
  var out=document.getElementById('faceout');
  if(!wrap||!grid||!out)return;
  fetch('wall.json',{cache:'no-store'}).then(function(r){return r.json();}).then(function(W){
   if(!W||!W.people||!W.people.length)return;
   wrap.hidden=false;
   grid.style.setProperty('--wg',W.grid);
   var cur=-1;
   W.people.forEach(function(pe,i){
    var b=document.createElement('button');
    b.type='button';
    b.className='ft wt-'+i;
    b.setAttribute('aria-pressed','false');
    b.setAttribute('aria-label',(pe.y?pe.y+'　':'')+pe.n+'枚の写真に写っている人');
    b.addEventListener('click',function(){ open_(i,b); });
    grid.appendChild(b);
   });
   function open_(i,btn){
    grid.querySelectorAll('.ft[aria-pressed="true"]').forEach(function(x){
     x.setAttribute('aria-pressed','false');});
    if(cur===i){ cur=-1; out.hidden=true; out.innerHTML=''; return; }
    cur=i; btn.setAttribute('aria-pressed','true');
    var pe=W.people[i];
    var h=document.createElement('div'); h.className='faceout-h';
    var bb=document.createElement('b'); bb.textContent='この人が写っている写真　'+pe.n+'枚';
    h.appendChild(bb);
    if(pe.y){ var yy=pe.y.split('-');
              var sp=document.createElement('span');
              sp.textContent=(yy[0]===yy[1]?yy[0]:yy[0]+'〜'+yy[1])+'年';
              h.appendChild(sp); }
    var x=document.createElement('button'); x.type='button'; x.className='fo-x';
    x.setAttribute('aria-label','閉じる'); x.textContent='×';
    x.addEventListener('click',function(){ open_(i,btn); });
    h.appendChild(x);
    var g=document.createElement('div'); g.className='gallery';
    pe.p.forEach(function(id){
     var im=document.createElement('img');
     im.loading='lazy'; im.decoding='async'; im.alt='';
     im.src='wall/t'+id+'.jpg';
     im.dataset.full='wall/g'+id+'.jpg';
     g.appendChild(im);
    });
    out.innerHTML=''; out.appendChild(h); out.appendChild(g); out.hidden=false;
    out.scrollIntoView({behavior:'smooth',block:'nearest'});
   }
  }).catch(function(){});
 }catch(e){}
})();


/* ===== ページ全体を斜めの帯にして、その軸上を進む =====
   画面上の位置 = T + R(A)・P。P=(列幅/2, s) が画面中央に来るように T を決める。
   s はスクロール量そのものなので、ふつうに縦スクロールするだけで
   視点が斜めに進んでいく。ホイールは乗っ取らない。 */
(function(){
 try{
  var track=document.getElementById('track'), world=document.getElementById('world');
  if(!track||!world) return;
  var rm=matchMedia('(prefers-reduced-motion: reduce)');
  var A=0,cosA=1,sinA=0,cw=1040,H=0,vw=0,vh=0,ready=false;

  function layout(){
   if(rm.matches){ track.style.height=''; world.style.transform=''; ready=false; return; }
   vw=innerWidth; vh=innerHeight;
   /* 狭い画面ほど角度を寝かせる。でないと列が細くなりすぎて読めない */
   var deg = vw<760 ? 6 : (vw<1100 ? 9 : 12);
   A=-deg*Math.PI/180;               /* 右下へ進む向き */
   cosA=Math.cos(A); sinA=Math.sin(A);
   document.documentElement.style.setProperty('--ang',deg+'deg');
   /* 回しても画面に収まる列幅 */
   var pad = vw<760 ? 12 : 24;
   var w = (vw-pad*2 - vh*Math.abs(sinA))/Math.abs(cosA);
   cw = Math.max(238, Math.min(1040, w));
   world.style.setProperty('--cw', cw.toFixed(0)+'px');
   H = world.offsetHeight;
   track.style.height = (H+vh)+'px';
   ready=true;
  }
  var FORCE=null;                     /* 検証用: s を直接与える */
  function apply(){
   if(!ready) return;
   var s=(FORCE===null?scrollY:FORCE)+vh/2, px=cw/2;
   var tx=vw/2-(cosA*px-sinA*s), ty=vh/2-(sinA*px+cosA*s);
   world.style.transform='translate3d('+tx.toFixed(1)+'px,'+ty.toFixed(1)+'px,0) rotate('+(A*180/Math.PI).toFixed(2)+'deg)';
  }
  var raf=0;
  function tick(){ raf=0; apply(); }
  function onScroll(){ if(!raf) raf=requestAnimationFrame(tick); }

  /* 検証用: ?wy=<scrollY> でその位置を同期で描く */
  var _wy=new URLSearchParams(location.search).get('wy');

  function boot(){
   layout();
   if(_wy!==null) FORCE=+_wy;
   apply();
  }
  boot();
  addEventListener('scroll',onScroll,{passive:true});
  addEventListener('resize',function(){layout();apply();},{passive:true});
  addEventListener('load',boot);
  /* 画像が入って高さが変わるので測り直す */
  if(window.ResizeObserver){
   var ro=new ResizeObserver(function(){ if(!rm.matches){ H=world.offsetHeight;
     track.style.height=(H+vh)+'px'; apply(); } });
   ro.observe(world);
  }
  if(rm.addEventListener) rm.addEventListener('change',function(){layout();apply();});
 }catch(e){}
})();


/* ===== 章のドット絵を立体にして回す（描画器は自前） =====
   平面のドット絵を奥行き方向に押し出し、Y軸で回してX軸で少し傾ける。
   遠近法はなし。裏向きの面は捨て、残りを奥から順に塗る。 */
(function(){
 try{
  if(!window.PXV||!window.PXPAL) return;
  if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var boxes=document.querySelectorAll('.pxbox[data-px]');
  if(!boxes.length) return;
  var c0=document.createElement('canvas');
  if(!c0.getContext||!c0.getContext('2d')) return;

  var DEPTH=6, TILT=0.22, DPR=Math.min(2,devicePixelRatio||1);
  var LX=-0.45, LY=-0.78, LZ=-0.44;   /* 光の向き（左上手前から） */

  function rgb(hex,f){
   var n=parseInt(hex.slice(1),16);
   var R=(n>>16)&255,G=(n>>8)&255,B=n&255;
   R=Math.min(255,Math.round(R*f));
   G=Math.min(255,Math.round(G*f));
   B=Math.min(255,Math.round(B*f));
   return 'rgb('+R+','+G+','+B+')';
  }
  /* 横に続く同じ色を1つの箱にまとめる */
  function build(rows){
   var w=0,i;
   for(i=0;i<rows.length;i++) if(rows[i].length>w) w=rows[i].length;
   var bs=[];
   for(var y=0;y<rows.length;y++){
    var row=rows[y];
    for(var x=0;x<row.length;){
     var ch=row.charAt(x);
     if(ch==='.'){x++;continue;}
     var k=1; while(x+k<row.length&&row.charAt(x+k)===ch) k++;
     bs.push([x,x+k,y,y+1,PXPAL[ch]||'#060000']);
     x+=k;
    }
   }
   return {w:w,h:rows.length,bs:bs};
 }

  /* 箱の6面。[頂点4つ, 法線] を模型座標で返す */
  function faces(b){
   var x0=b[0],x1=b[1],y0=b[2],y1=b[3],z0=0,z1=DEPTH;
   return [
    [[[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0]],[0,0,-1]],  /* 手前 */
    [[[x1,y0,z1],[x0,y0,z1],[x0,y1,z1],[x1,y1,z1]],[0,0,1]],   /* 奥   */
    [[[x0,y0,z1],[x0,y0,z0],[x0,y1,z0],[x0,y1,z1]],[-1,0,0]],  /* 左   */
    [[[x1,y0,z0],[x1,y0,z1],[x1,y1,z1],[x1,y1,z0]],[1,0,0]],   /* 右   */
    [[[x0,y0,z1],[x1,y0,z1],[x1,y0,z0],[x0,y0,z0]],[0,-1,0]],  /* 上   */
    [[[x0,y1,z0],[x1,y1,z0],[x1,y1,z1],[x0,y1,z1]],[0,1,0]]    /* 下   */
   ];
  }

  var items=[];
  for(var i=0;i<boxes.length;i++){
   var el=boxes[i], key=el.getAttribute('data-px'), rows=PXV[key];
   if(!rows) continue;
   var m=build(rows);
   var cv=document.createElement('canvas');
   cv.setAttribute('role','img');
   cv.setAttribute('aria-label',(el.querySelector('svg')&&el.querySelector('svg').getAttribute('aria-label'))||'');
   el.appendChild(cv); el.classList.add('on');
   items.push({el:el,cv:cv,ctx:cv.getContext('2d'),m:m,near:false,th:0});
  }
  if(!items.length) return;

  function resize(it){
   var cw=it.el.clientWidth||160;
   var ch=Math.round(cw*0.82);
   it.cv.style.height=ch+'px';
   it.cv.width=Math.round(cw*DPR); it.cv.height=Math.round(ch*DPR);
   it.cw=cw; it.chh=ch;
   var m=it.m;
   it.s=Math.min(cw/(m.w+DEPTH+2), ch/(m.h+DEPTH*0.9+2));
  }

  function draw(it){
   var ctx=it.ctx,m=it.m,S=it.s*DPR;
   var cw=it.cv.width, chh=it.cv.height;
   ctx.clearRect(0,0,cw,chh);
   var cT=Math.cos(it.th), sT=Math.sin(it.th);
   var cP=Math.cos(TILT), sP=Math.sin(TILT);
   var ox=m.w/2, oy=m.h/2, oz=DEPTH/2;
   function proj(p){
    var x=p[0]-ox, y=p[1]-oy, z=p[2]-oz;
    var X=x*cT+z*sT, Z=-x*sT+z*cT;
    var Y=y*cP-Z*sP, Z2=y*sP+Z*cP;
    return [X*S+cw/2, Y*S+chh/2, Z2];
   }
   var list=[];
   for(var i=0;i<m.bs.length;i++){
    var b=m.bs[i], fs=faces(b);
    for(var f=0;f<6;f++){
     var nrm=fs[f][1];
     /* 法線も同じ向きに回す */
     var nX=nrm[0]*cT+nrm[2]*sT, nZ=-nrm[0]*sT+nrm[2]*cT;
     var nY=nrm[1]*cP-nZ*sP, nZ2=nrm[1]*sP+nZ*cP;
     if(nZ2>=-0.001) continue;                 /* 裏向きは描かない */
     var q=fs[f][0], pts=[proj(q[0]),proj(q[1]),proj(q[2]),proj(q[3])];
     var zc=(pts[0][2]+pts[1][2]+pts[2][2]+pts[3][2])/4;
     var lam=-(nX*LX+nY*LY+nZ2*LZ);
     if(lam<0) lam=0;
     list.push([zc,pts,rgb(b[4],0.62+0.5*lam)]);
    }
   }
   list.sort(function(a,b){return b[0]-a[0];});   /* 奥から手前へ */
   for(var i=0;i<list.length;i++){
    var pts=list[i][1];
    ctx.beginPath();
    ctx.moveTo(pts[0][0],pts[0][1]);
    ctx.lineTo(pts[1][0],pts[1][1]);
    ctx.lineTo(pts[2][0],pts[2][1]);
    ctx.lineTo(pts[3][0],pts[3][1]);
    ctx.closePath();
    ctx.fillStyle=list[i][2];
    ctx.fill();
    ctx.strokeStyle=list[i][2];
    ctx.lineWidth=1; ctx.stroke();          /* 継ぎ目の隙間を埋める */
   }
  }

  var forced=new URLSearchParams(location.search).get('vox');
  function update(){
   for(var i=0;i<items.length;i++){
    var it=items[i];
    if(!it.near) continue;
    var r=it.el.getBoundingClientRect();
    var pr=(r.top+r.height/2)/(innerHeight||1);
    if(pr<0)pr=0; else if(pr>1)pr=1;
    it.th=(forced!==null)?(+forced):((0.5-pr)*1.10);
    draw(it);
   }
  }
  var raf=0;
  function sched(){ if(!raf) raf=requestAnimationFrame(function(){raf=0;update();}); }

  if(window.IntersectionObserver){
   var io=new IntersectionObserver(function(es){
    for(var i=0;i<es.length;i++){
     var it=es[i].target.__v; if(!it) continue;
     it.near=es[i].isIntersecting;
     if(it.near&&!it.sized){ resize(it); it.sized=true; }
    }
    sched();
   },{rootMargin:'40% 0px 40% 0px'});
   for(var i=0;i<items.length;i++){ items[i].el.__v=items[i]; io.observe(items[i].el); }
  }else{
   for(var i=0;i<items.length;i++){ items[i].near=true; resize(items[i]); items[i].sized=true; }
  }
  addEventListener('scroll',sched,{passive:true});
  addEventListener('resize',function(){
   for(var i=0;i<items.length;i++) if(items[i].sized) resize(items[i]);
   sched();
  },{passive:true});
  addEventListener('load',function(){
   for(var i=0;i<items.length;i++) if(items[i].near&&!items[i].sized){resize(items[i]);items[i].sized=true;}
   sched();
  });
  sched();
 }catch(e){}
})();


/* ===== 左右の街を立体にして回す =====
   街は縦に66,000px以上ある。そんなcanvasは作れないので、
   画面2つぶんの高さのcanvasを .world の中に置き、
   スクロールが進んだら置き直して描き直す。
   .world の中にあるので、ページの傾きと移動には自動でついてくる。 */
(function(){
 try{
  if(!window.TOWNV) return;
  if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  if(innerWidth<=900) return;
  var boxesL=document.querySelector('.twl'), boxesR=document.querySelector('.twr');
  if(!boxesL||!boxesR) return;
  var probe=document.createElement('canvas');
  if(!probe.getContext||!probe.getContext('2d')) return;

  var DEPTH=3, TILT=0.20, DPR=Math.min(2,devicePixelRatio||1);
  var LX=-0.45, LY=-0.78, LZ=-0.44;
  var PAL=TOWNV.c;

  function rgb(hex,f,sat){
   var v=parseInt(hex.slice(1),16);
   var R=((v>>16)&255)*f, G=((v>>8)&255)*f, B=(v&255)*f;
   if(sat!==undefined&&sat<1){
    var L=0.299*R+0.587*G+0.114*B;
    R=L+(R-L)*sat; G=L+(G-L)*sat; B=L+(B-L)*sat;
   }
   return 'rgb('+Math.min(255,Math.round(R))+','+Math.min(255,Math.round(G))+','+Math.min(255,Math.round(B))+')';
  }
  /* 絵ごとに、横に続く同じ色をまとめた箱の並びを作る */
  /* 同じ色のかたまりを、横だけでなく縦にもまとめる。
     塗る面の数がおよそ半分になり、スクロール中の負荷が下がる */
  var MODELS=TOWNV.s.map(function(rows){
   var h=rows.length, w=0, i, y, x;
   for(i=0;i<h;i++) if(rows[i].length>w) w=rows[i].length;
   var g=[];
   for(y=0;y<h;y++){
    var r=rows[y], line=[];
    for(x=0;x<w;x++){
     var c=x<r.length?r.charAt(x):'.';
     line.push((c==='.'||c===' ')?null:(PAL[c]||'#A8BECC'));
    }
    g.push(line);
   }
   var bs=[];
   for(y=0;y<h;y++){
    for(x=0;x<w;){
     var col=g[y][x];
     if(!col){x++;continue;}
     var x1=x+1; while(x1<w&&g[y][x1]===col) x1++;
     var y1=y+1;
     for(;y1<h;y1++){
      var ok=true;
      for(var xx=x;xx<x1;xx++) if(g[y1][xx]!==col){ok=false;break;}
      if(!ok) break;
     }
     for(var yy=y;yy<y1;yy++) for(var xx2=x;xx2<x1;xx2++) g[yy][xx2]=null;
     bs.push([x,x1,y,y1,col]);
     x=x1;
    }
   }
   return {w:w,h:h,bs:bs};
  });

  var NBLD=TOWNV.nb||11;              /* ここから先が人や動物 */
  var sides=[{el:boxesL,side:0,pl:[],chs:[]},{el:boxesR,side:1,pl:[],chs:[]}];

  /* 章の位置は組んでみないと分からないので実行時に測る */
  function topInWorld(el){
   var W=document.getElementById('world'), y=0, n=el;
   while(n&&n!==W){ y+=n.offsetTop; n=n.offsetParent; }
   return y;
  }
  /* 章ごとに、その章の建物だけを置いていく */
  function buildPlaces(){
   sides[0].pl=[]; sides[1].pl=[];
   sides[0].chs=[]; sides[1].chs=[];
   if(!window.TOWNS) return;
   for(var ci=0;ci<TOWNS.length;ci++){
    var ch=TOWNS[ci];
    var sec=null, all=document.querySelectorAll('section[data-chname]');
    for(var q=0;q<all.length;q++){
     if(all[q].getAttribute('data-chname').indexOf(ch.n)===0){ sec=all[q]; break; }
    }
    if(!sec) continue;
    var top=topInWorld(sec), H=sec.offsetHeight;
    for(var sd=0;sd<2;sd++){
     var seed=(ci+1)*7919+sd*104729;
     var rnd=function(){ seed=(seed*1103515245+12345)&0x7FFFFFFF; return seed/0x7FFFFFFF; };
     /* 建物。足元をばらし、ときどき1軒とばす */
     var y=top+40;
     while(y<top+H-40){
      var x=10+rnd()*38, cnt=0, base=y+rnd()*26;
      while(x<404&&cnt<ch.m){
       var k=ch.k[(rnd()*ch.k.length)|0], mo=MODELS[k];
       var wpx=24+rnd()*38;
       if(mo.h>mo.w) wpx=20+rnd()*16;
       if(rnd()<0.16){ x+=wpx*0.7+rnd()*26; cnt++; continue; }   /* 空き地 */
       var gy=base+(rnd()-0.5)*30;
       var ox=(sd===0)?(440-x-wpx):x;
       var sat=Array.isArray(ch.s)?(ch.s[0]+(ch.s[1]-ch.s[0])*Math.min(1,Math.max(0,(gy-top)/H))):(ch.s==null?1:ch.s);
       sides[sd].pl.push([k,(ox)|0,(gy)|0,(wpx)|0,sat]);
       x+=wpx+2+rnd()*26; cnt++;
      }
      y+=ch.g*(0.72+rnd()*0.56);
     }
     /* 人や動物。縮尺は気にせず、建物と同じくらい大きく出す */
     if(ch.c&&ch.c.length){
      var y2=top+30;
      while(y2<top+H-30){
       var many=1+((rnd()*2.4)|0);
       for(var q=0;q<many;q++){
        var k2=ch.c[(rnd()*ch.c.length)|0], m2=MODELS[k2];
        var w2=30+rnd()*28;
        if(m2.h>m2.w*1.6) w2=24+rnd()*16;
        var x2=8+rnd()*396;
        var gy2=y2+(rnd()-0.5)*70;
        var ox2=(sd===0)?(440-x2-w2):x2;
        var kk=k2-NBLD;
        var mv=(kk===4||kk===5)?(rnd()<0.5?1:-1):0;   /* 軽トラと電車は走る */
        var sat2=Array.isArray(ch.s)?(ch.s[0]+(ch.s[1]-ch.s[0])*Math.min(1,Math.max(0,(gy2-top)/H))):(ch.s==null?1:ch.s);
        sides[sd].chs.push([k2,(ox2)|0,(gy2)|0,(w2)|0,rnd()*6.283,mv,sat2]);
       }
       y2+=ch.cg*(0.6+rnd()*0.8);
      }
     }
    }
   }
   sides[0].pl.sort(function(a,b){return a[2]-b[2];});
   sides[1].pl.sort(function(a,b){return a[2]-b[2];});
  }
  sides.forEach(function(sd){
   sd.cv=document.createElement('canvas');
   sd.ctx=sd.cv.getContext('2d');
   sd.cv2=document.createElement('canvas');     /* 動くものはこちら */
   sd.ctx2=sd.cv2.getContext('2d');
   sd.el.appendChild(sd.cv);
   sd.el.appendChild(sd.cv2);
   sd.el.classList.add('on');
   sd.top=null;
  });

  function drawSide(sd,bandTop,bandH,th,lo,hi){
   var ctx=sd.ctx, W=440;
   var cT=Math.cos(th), sT=Math.sin(th), cP=Math.cos(TILT), sP=Math.sin(TILT);
   ctx.setTransform(1,0,0,1,0,0);
   ctx.clearRect(0,0,sd.cv.width,sd.cv.height);
   ctx.setTransform(DPR,0,0,DPR,0,0);
   for(var i=0;i<sd.pl.length;i++){
    var pl=sd.pl[i], gy=pl[2];
    if(gy<lo-260) continue;
    if(gy>hi+80) break;                 /* 上から順に並んでいるので抜けられる */
    drawOne(ctx,MODELS[pl[0]],pl[1],gy-bandTop,pl[3],cT,sT,cP,sP,pl[4]);
   }
  }

  function drawOne(ctx,m,ox,oy,wpx,cT,sT,cP,sP,sat){
   var S=wpx/m.w;                 /* 1マスあたりの大きさ */
   var cx=m.w/2, cy=m.h/2, cz=DEPTH/2;
   var px=ox+wpx/2, py=oy-(m.h*S)/2;   /* 足元を基準に置く */
   function pr(x,y,z){
    var X=(x-cx)*S, Y=(y-cy)*S, Z=(z-cz)*S;
    var X1=X*cT+Z*sT, Z1=-X*sT+Z*cT;
    var Y2=Y*cP-Z1*sP, Z2=Y*sP+Z1*cP;
    return [px+X1, py+Y2, Z2];
   }
   var list=[];
   for(var i=0;i<m.bs.length;i++){
    var b=m.bs[i], x0=b[0],x1=b[1],y0=b[2],y1=b[3],z0=0,z1=DEPTH;
    var F=[
     [[[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0]],0,0,-1],
     [[[x1,y0,z1],[x0,y0,z1],[x0,y1,z1],[x1,y1,z1]],0,0,1],
     [[[x0,y0,z1],[x0,y0,z0],[x0,y1,z0],[x0,y1,z1]],-1,0,0],
     [[[x1,y0,z0],[x1,y0,z1],[x1,y1,z1],[x1,y1,z0]],1,0,0],
     [[[x0,y0,z1],[x1,y0,z1],[x1,y0,z0],[x0,y0,z0]],0,-1,0],
     [[[x0,y1,z0],[x1,y1,z0],[x1,y1,z1],[x0,y1,z1]],0,1,0]
    ];
    for(var f=0;f<6;f++){
     var nx=F[f][1],ny=F[f][2],nz=F[f][3];
     var NX=nx*cT+nz*sT, NZ=-nx*sT+nz*cT;
     var NY=ny*cP-NZ*sP, NZ2=ny*sP+NZ*cP;
     if(NZ2>=-0.001) continue;
     var q=F[f][0];
     var p0=pr(q[0][0],q[0][1],q[0][2]),p1=pr(q[1][0],q[1][1],q[1][2]),
         p2=pr(q[2][0],q[2][1],q[2][2]),p3=pr(q[3][0],q[3][1],q[3][2]);
     var lam=-(NX*LX+NY*LY+NZ2*LZ); if(lam<0)lam=0;
     list.push([(p0[2]+p1[2]+p2[2]+p3[2])/4,p0,p1,p2,p3,rgb(b[4],0.78+0.34*lam,sat)]);
    }
   }
   list.sort(function(a,b){return b[0]-a[0];});
   for(var i=0;i<list.length;i++){
    var L=list[i];
    ctx.beginPath();
    ctx.moveTo(L[1][0],L[1][1]); ctx.lineTo(L[2][0],L[2][1]);
    ctx.lineTo(L[3][0],L[3][1]); ctx.lineTo(L[4][0],L[4][1]);
    ctx.closePath();
    ctx.fillStyle=L[5]; ctx.fill();
    ctx.strokeStyle=L[5]; ctx.lineWidth=.6; ctx.stroke();
   }
  }

  var lastTh=null, bandTop=null, bandH=0, raf=0;
  var _q=new URLSearchParams(location.search);
  var forced=_q.get('vt'), fy=_q.get('wy');   /* 検証用 */

  function update(){
   raf=0;
   var vh=innerHeight;
   var s=((fy!==null)?+fy:scrollY)+vh/2;
   /* 回さず、揺らす。増え続けると横顔（輪郭色の面）ばかりになるため */
   var th=(forced!==null)?(+forced):(Math.sin(s/2600)*0.5);
   var need=false;
   if(bandTop===null||s<bandTop+vh*0.6||s>bandTop+bandH-vh*0.6){
    bandH=Math.round(vh*2.2); bandTop=Math.round(s-bandH/2); need=true;
    sides.forEach(function(sd){
     sd.el.style.top=bandTop+'px';
     sd.el.style.height=bandH+'px';
     sd.cv.style.height=bandH+'px';
     sd.cv.width=Math.round(440*DPR); sd.cv.height=Math.round(bandH*DPR);
     sd.cv2.style.height=bandH+'px';
     sd.cv2.width=Math.round(440*DPR); sd.cv2.height=Math.round(bandH*DPR);
    });
   }
   if(!need&&lastTh!==null&&Math.abs(th-lastTh)<0.02) return;
   lastTh=th;
   var lo=s-vh*0.85, hi=s+vh*0.85;
   sides.forEach(function(sd){ drawSide(sd,bandTop,bandH,th,lo,hi); });
  }
  /* 動くものだけを描く。建物は触らない */
  function drawChars(sd,t){
   if(bandTop===null) return;
   var ctx=sd.ctx2;
   var th=(lastTh===null)?0:lastTh;
   ctx.setTransform(1,0,0,1,0,0);
   ctx.clearRect(0,0,sd.cv2.width,sd.cv2.height);
   ctx.setTransform(DPR,0,0,DPR,0,0);
   var vh=innerHeight;
   var s=((fy!==null)?+fy:scrollY)+vh/2;
   var lo=s-vh*0.85, hi=s+vh*0.85;
   var cP=Math.cos(TILT), sP=Math.sin(TILT);
   for(var i=0;i<sd.chs.length;i++){
    var c=sd.chs[i], gy=c[2];
    if(gy<lo-220||gy>hi+80) continue;
    var thc=th+Math.sin(t*0.9+c[4])*0.12;      /* ゆっくり首を振る */
    var cT=Math.cos(thc), sT=Math.sin(thc);
    var ox=c[1], oy=gy-bandTop;
    var model=MODELS[c[0]];
    var frames=TOWNV.fr&&TOWNV.fr[String(c[0])];
    if(frames){
     /* コマ送り。260ms/コマのカクつきがピクセルの質感を作る（y-n10実測250ms） */
     var step=Math.floor(t/0.26+c[4]*2)%frames.length;
     model=MODELS[frames[step]];
     oy+=(step%2);                              /* コマに合わせた1pxの段差 */
    }
    if(c[5]){                                   /* 軽トラと電車は走る */
     var L=560;
     ox=(((c[1]+t*26*c[5])%L)+L)%L-60;
    }else if(!frames){
     oy+=Math.sin(t*2.1+c[4])*(1.2+c[3]*0.05); /* その場で弾む */
    }
    drawOne(ctx,model,ox,oy,c[3],cT,sT,cP,sP,c[6]);
   }
  }
  var animRaf=0, lastAnim=0;
  function animTick(ts){
   animRaf=requestAnimationFrame(animTick);
   if(ts-lastAnim<33) return;                   /* 30fpsまで */
   lastAnim=ts;
   var t=ts/1000;
   for(var i=0;i<sides.length;i++) drawChars(sides[i],t);
  }
  animRaf=requestAnimationFrame(animTick);

  function sched(){ if(!raf) raf=requestAnimationFrame(update); }
  function relayout(){ buildPlaces(); bandTop=null; lastTh=null; sched(); }
  addEventListener('scroll',sched,{passive:true});
  addEventListener('resize',relayout,{passive:true});
  addEventListener('load',relayout);
  /* 画像が入って章の高さが変わるので測り直す */
  if(window.ResizeObserver){
   var wro=new ResizeObserver(function(){ relayout(); });
   wro.observe(document.getElementById('world'));
  }
  relayout();
 }catch(e){}
})();


/* ===== つづきを読む（ダイジェストの開閉） ===== */
document.addEventListener('click',function(e){
 var b=e.target.closest&&e.target.closest('.morebtn');
 if(!b) return;
 var sec=b.closest('section');
 if(!sec) return;
 var open=sec.classList.toggle('open');
 b.textContent=open?'たたむ':'つづきを読む';
});
